  MSD.cls('#cd-strip', 'bad', tone === 'bad');
  MSD.cls('#cd-strip', 'good', tone === 'good');
  MSD.q('#cd-strip-l').textContent = label;
  MSD.q('#cd-strip-t').textContent = text;
};

CD.phone = function(i, tile, time, tone){
  MSD.q('#cd-tile-' + i).textContent = tile;
  MSD.q('#cd-ph-t-' + i).textContent = time;
  MSD.cls('#cd-ph-' + i, 'bad', tone === 'bad');
  MSD.cls('#cd-ph-' + i, 'good', tone === 'good');
};
CD.phones = function(tile, time, tone){ for(var i = 1; i <= 3; i++) CD.phone(i, tile, time, tone); };

CD.ar = function(row, i, tone){
  ['live','bad','ok','dim'].forEach(function(c){ MSD.cls('#cd-a' + row + '-' + i, c, tone === c); });
};
CD.ars = function(row, tone){ for(var i = 1; i <= 3; i++) CD.ar(row, i, tone); };

CD.edge = function(i, on, tone, chip, chipTone){
  var el = '#cd-edge-' + i;
  MSD.cls(el, 'slot', !on);
  ['live','ok','bad'].forEach(function(c){ MSD.cls(el, c, tone === c); });
  MSD.q('#cd-edge-t-' + i).textContent = on ? 'Front Door edge' : 'no copy nearby';
  var v = MSD.q('#cd-edge-v-' + i);
  v.textContent = chip || '—';
  ['ok','bad','warn'].forEach(function(c){ v.classList.toggle(c, chipTone === c); });
};
CD.edges = function(on, tone, chip, chipTone){ for(var i = 1; i <= 3; i++) CD.edge(i, on, tone, chip, chipTone); };

// The origin: App Service before the fix, Blob Storage after it.
CD.origin = function(kind, tone){
  var blob = kind === 'blob';
  MSD.cls('#cd-o-ic-app', 'off', blob);
  MSD.cls('#cd-o-ic-blob', 'off', !blob);
  MSD.q('#cd-o-t').textContent = blob ? 'Blob Storage' : 'App Service';
  MSD.q('#cd-o-s').textContent = blob ? 'the original, asked only on a miss' : 'serving every photo itself';
  ['live','ok','bad'].forEach(function(c){ MSD.cls('#cd-origin', c, tone === c); });
};

// Outbound bandwidth on a 0-4 GB/s scale.
CD.meter = function(gb, tone, label){
  var f = MSD.q('#cd-fill');
  f.style.width = Math.min(100, gb / 4 * 100) + '%';
  f.classList.toggle('bad', tone === 'bad');
  f.classList.toggle('ok', tone === 'ok');
  var v = MSD.q('#cd-o-v');
  v.textContent = label || (gb + ' GB/s');
  ['ok','bad','warn'].forEach(function(c){ v.classList.toggle(c, tone === c); });
};

CD.file = function(text, isNew){
  MSD.q('#cd-file').textContent = text;
  MSD.cls('#cd-file', 'new', !!isNew);
};

// Bytes travelling between two rows, in one column.
CD.flow = function(col, fromRow, toRow, opts){
  opts = opts || {};
  return MSD.stream('#cd-scene', { from:{ x:CD.X[col], y:CD.Y[fromRow] }, to:{ x:CD.X[col], y:CD.Y[toRow] },
    count: opts.count || 4, duration: opts.duration || 650, spread: 24, gap: opts.gap || 480, silent: opts.silent });
};
CD.once = function(fromX, fromRow, toX, toRow, n){
  MSD.particles('#cd-scene', { from:{ x:fromX, y:CD.Y[fromRow] }, to:{ x:toX, y:CD.Y[toRow] }, count:n || 6, duration:700, spread:20 });
};

